import base64,hashlib,html,json,shutil,os
from pathlib import Path
from playwright.sync_api import sync_playwright
R=Path(__file__).resolve().parents[1]; E=R/'evidence/run-20261011T224758Z'; O=R/'reports';O.mkdir(exist_ok=True)
data=json.loads((E/'results.json').read_text());triage=json.loads((E/'triage.json').read_text())
def img(name):return 'data:image/png;base64,'+base64.b64encode((E/name).read_bytes()).decode()
def table(headers,rows):return '<table><thead><tr>'+''.join('<th>'+html.escape(x)+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+html.escape(str(c))+'</td>' for c in row)+'</tr>' for row in rows)+'</tbody></table>'
def box(title,text):return f'<aside><b>{title}</b><p>{text}</p></aside>'
pages=[]
def page(k,title,body):pages.append(f'<section class="page"><div class="kicker">RAPPORT TECHNIQUE / {k}</div><h1>{title}</h1>{body}<footer><span>WAEL RDIFI · RIM MENZLI / SSIR-5-F</span><span>MALWARE ANALYSIS LAB · {len(pages)+1:02}</span></footer></section>')
pages.append('''<section class="page cover"><div class="kicker">CLASSE SSIR-5-F</div><p class="document-type">RAPPORT DE PROJET</p><h1>Laboratoire de détection<br>des cybermenaces</h1><h2>Malware Analysis Lab</h2><div class="coverline"></div><p class="scope">Conception d’un environnement isolé sous WSL2 et Docker,<br>analyse du trafic réseau et validation de protections.<br>Extension d’analyse statique avec MCP et OpenCode.</p><div class="authors"><span class="label">PRÉSENTÉ PAR</span><br>WAEL RDIFI<br>RIM MENZLI</div><p class="subtitle">12 octobre 2026</p><div class="cover-note">Environnement pédagogique<br>Analyse fondée sur des captures et des tests reproductibles</div><footer><span>SSIR-5-F</span><span>RAPPORT TECHNIQUE</span></footer></section>''')
page('01 / SYNTHÈSE','Synthèse du projet', '''<p class="lead">Un laboratoire léger et reproductible pour observer des attaques contrôlées, vérifier leur effet et mesurer les protections à partir de preuves techniques.</p><h2>Résumé exécutif</h2><p>Le projet utilise une station d’analyse et une cible HTTP sur un réseau Docker interne, sous WSL2. Deux phases comparables : vulnérable puis durcie : démontrent la reconnaissance réseau, une rafale de tentatives de connexion et une injection SQL sur des données fictives.</p><p>Les captures PCAP, les journaux applicatifs et les réponses JSON sont corrélés. Sept contrôles fonctionnels réussissent et six alertes sont produites. Un MCP local permet à OpenCode de consulter les preuves et d’effectuer un triage statique borné.</p>'''+table(['Indicateur','Résultat'],[['Exécution de référence',E.name],['Périmètre réseau','101 ports TCP; service HTTP 8080'],['Captures','2 PCAP et 4 captures PNG'],['Mémoire configurée','128 MiB cible + 384 MiB station'],['Mémoire au repos mesurée','Environ 33 MiB pour les deux services'],['Intégration IA','MCP SDK et connexion OpenCode vérifiés; appel LLM manuel']])+box('Décision d’architecture','Docker remplace ici les deux VM pour réduire la consommation. Les conteneurs partagent le noyau WSL2 : cette architecture ne fournit pas une isolation de type VM.'))
page('02 / CADRAGE','Objectifs et organisation',table(['Exigence','Mise en œuvre / preuve'],[['Environnement isolé','Deux conteneurs, réseau interne, aucun port publié'],['Reconnaissance','Nmap TCP connect et vérification HTTP Netcat'],['Analyse du trafic','dumpcap, PCAP, TShark, tcpdump et Wireshark GUI'],['Attaques contrôlées','Scan, connexion répétée, tautologie SQL'],['Détection / mitigation','Trois règles; SQL paramétré et limitation des échecs'],['Livrables','Code, PCAP, captures, rapport, slides et guide vidéo']])+ '<h2>Workflow de validation</h2>'+table(['Étape','Objectif','Livrable'],[['1','Définir les scénarios et la topologie','Compose et modèle de menace'],['2','Identifier hôtes, ports et services','Nmap XML/TXT et Netcat'],['3','Capturer et analyser le trafic','PCAP, TSV SYN/HTTP'],['4','Exécuter les scénarios','Résultats JSON et journaux'],['5','Corréler et vérifier les protections','Alertes et comparaison avant/après'],['6','Finaliser et présenter','Rapport, dossier de preuves et runbook']])+box('Traçabilité pédagogique','Ce tableau décrit les étapes de validation et les artefacts associés à chaque étape.'))
page('03 / ARCHITECTURE','Architecture du laboratoire', '''<div class="topology"><div>STATION<br><b>172.31.0.3</b><small>scan · capture · analyse</small></div><strong>→ HTTP 8080 →</strong><div>CIBLE<br><b>172.31.0.2</b><small>application pédagogique</small></div></div><p>Réseau interne <code>malware-analysis-lab_lab</code>. Aucun port n’est publié. La station observe son propre trafic vers la cible; elle n’est pas présentée comme un capteur passif de tout le bridge.</p>'''+table(['Service','RAM','CPU','PID','Privilèges'],[['Cible','128 MiB','0,50','64','UID 1000; capacités nulles'],['Station','384 MiB','0,75','128','Capture UID 0; NET_RAW uniquement'],['Worker statique','Dans la station','Budget partagé','Budget partagé','UID/GID 65534; capacités nulles']])+'''<h2>Flux des preuves</h2><p>Scénario → capture PCAP → extraction TShark → corrélation avec événements JSONL → résultats et alertes → dashboard → consultation MCP.</p><h2>Gestion des ressources</h2><p>Le plafond cumulé des services est de 512 MiB et 1,25 CPU. Docker et WSL2 ajoutent leur propre consommation. La limite de swap n’est pas supportée par le noyau de cette session; le plafond de RAM est vérifié.</p>'''+box('Séparation du moteur','Le laboratoire utilise un moteur Docker dédié et un stockage local distinct. Le socket Docker n’est jamais monté dans les conteneurs; le MCP de confiance orchestre les opérations depuis l’hôte.'))
page('04 / MÉTHODE','Méthodologie et outils',table(['Étape','Outil / méthode','Artefact'],[['Référence','Requête HTTP normale et lookup légitime','results.json'],['Reconnaissance','Nmap -sT -Pn -n; ports 1–100 et 8080','*-nmap.xml / .txt'],['Vérification service','Netcat et GET /health','*-netcat.txt'],['Capture','dumpcap eth0, sans mode promiscuous','vulnerable.pcap / hardened.pcap'],['Analyse hors ligne','TShark HTTP forcé sur TCP 8080; tcpdump UID 1000','*-http.tsv / *-syn.tsv / *-tcpdump.txt'],['Corrélation','Événements applicatifs avec identifiant de run','app.jsonl / alerts.json'],['Visualisation','Wireshark GUI et Chromium','Quatre images PNG']])+'''<h2>Reproductibilité</h2><pre>./scripts/start-dedicated-docker.sh
./scripts/lab.sh build
./scripts/lab.sh up
./scripts/lab.sh run
opencode --agent lab-analyst</pre><p>Le script fixe la cible et les scénarios. Chaque exécution crée un dossier horodaté distinct. Les requêtes sont bornées et utilisent exclusivement des comptes synthétiques. Le mode durci conserve les contrôles de fonctionnement normal.</p>'''+box('Intégrité','Les fichiers sont accompagnés d’un manifeste SHA-256. Il détecte les modifications par comparaison avec une copie conservée séparément; il ne constitue pas une signature contre un administrateur qui remplace aussi le manifeste.'))
page('05 / SCÉNARIOS','Scénarios de test', '''<h2>01 : Reconnaissance de ports</h2><p>La station tente des connexions TCP vers 101 ports distincts. Le port 8080 expose le service HTTP; les autres ports testés sont fermés. La règle SCAN_PORTS utilise un seuil de 20 ports distincts.</p><h2>02 : Rafale de connexion</h2><p>Six mots de passe incorrects sont soumis au compte fictif <code>labuser</code>, puis le mot de passe correct. La règle LOGIN_BURST recherche au moins trois échecs dans une fenêtre de 60 secondes.</p><h2>03 : Injection SQL pédagogique</h2><p>Le paramètre de recherche reçoit une tautologie de type <code>\' OR \'1\'=\'1</code>. La phase vulnérable concatène ce paramètre à la requête. La phase durcie utilise une requête paramétrée. La règle SQLI_PATTERN identifie cette forme précise dans l’URI décodée.</p>'''+table(['Signal','Observation','Limite d’interprétation'],[['Scan','101 ports distincts dans chaque phase','Un inventaire autorisé produit aussi ce signal'],['Échecs','6 vulnérable; 3 durcie puis HTTP 429','Une rafale seule ne prouve pas un accès réussi'],['SQLi','Trame 347 vulnérable; 345 durcie','Le succès doit être confirmé par la réponse']])+box('Périmètre contrôlé','Aucun déni de service, shell distant, donnée personnelle ou malware inconnu exécuté. L’interface /control sert uniquement à basculer le mode pédagogique; elle doit être retirée d’un déploiement réel.'))
page('06 / VALIDATION','Résultats et validation',table(['Observation','Vulnérable','Durcie'],[['HTTP normal','200','200'],['Recherche légitime','labuser','labuser'],['Six essais incorrects','401 × 6','401 × 3, puis 429 × 3'],['Connexion correcte après rafale','200; authenticated=true','429; rate_limited'],['Réponse à la tautologie SQL','labuser et analyst','Liste vide'],['Alertes produites','3 familles','3 familles']])+'''<h2>Sept assertions fonctionnelles réussies</h2><p>Service normal disponible; recherche légitime préservée; injection reproduite; injection mitigée; limitation des échecs active; connexion correcte possible en mode vulnérable; connexion correcte bloquée après rafale en mode durci.</p><h2>Effet et compromis</h2><p>La requête paramétrée supprime l’exposition des deux noms fictifs. La limitation par adresse bloque les essais au-delà de trois échecs pendant 60 secondes, mais bloque également temporairement une connexion légitime. Une adresse partagée derrière un NAT peut pénaliser plusieurs utilisateurs.</p><h2>Pourquoi les alertes persistent-elles ?</h2><p>La détection signale la tentative, même si la protection empêche son effet. Il faut donc distinguer comportement suspect, tentative empêchée et compromission confirmée.</p>'''+box('Recommandations','Combiner requêtes paramétrées, validation des entrées, droits minimaux SQL, MFA, temporisation et limites par compte et source. Réduire les services exposés et centraliser les journaux.'))
page('07 / PREUVES VISUELLES','Analyse des captures réseau',f'''<figure><img src="{img('wireshark-vulnerable.png')}"><figcaption>Phase vulnérable : observation des connexions TCP dans le PCAP réel.</figcaption></figure><figure><img src="{img('wireshark-hardened.png')}"><figcaption>Phase durcie : réponses HTTP 429 après activation de la limitation.</figcaption></figure><p class="fine">Captures GUI réalisées dans la station avec un affichage Xvfb privé. Aucun socket d’affichage de l’hôte n’est monté. Les PCAP restent disponibles pour examiner les trames et reconstruire les requêtes.</p>''')
page('08 / TABLEAU DE BORD','Tableau de bord et exploitation des résultats',f'''<figure class="dashboard"><img src="{img('dashboard-hardened.png')}"><figcaption>Dashboard interactif : comparaison des phases, réponses réelles et triage statique.</figcaption></figure><p>Le tableau de bord relie les résultats JSON aux artefacts techniques. Les tests Chromium vérifient les compteurs, le basculement entre phases et l’absence d’exécution d’une chaîne HTML hostile incluse dans le fichier de formation.</p>''')
page('09 / IA & MCP','Intégration MCP et OpenCode', '''<div class="flow">OpenCode ↔ MCP stdio ↔ orchestration Docker ↔ preuves</div>'''+table(['Outil MCP','Fonction bornée'],[['lab_status','Consulter l’état des services du projet'],['run_detection_demo','Exécuter le scénario fixe avec verrou de concurrence'],['list_evidence','Lister les dossiers de preuves autorisés'],['read_evidence','Lire un artefact autorisé avec validation du chemin'],['static_triage','Inspecter un fichier local autorisé sans exécution']])+'''<h2>Contrôles d’accès</h2><p>Les arguments de sous-processus sont fixés; aucun shell général ni cible réseau arbitraire n’est exposé. Traversées de chemin, liens symboliques, noms non autorisés et fichiers excessifs sont refusés. L’agent OpenCode <code>lab-analyst</code> autorise uniquement les outils MCP du laboratoire.</p><h2>Résultats d’intégration</h2><p>Le client SDK stdio vérifie les cinq outils, les cas de rejet, un scénario Docker complet et le triage. La connexion native OpenCode 1.18.35 est vérifiée séparément.</p>'''+box('État de la démonstration IA','Aucun appel à un modèle payant n’a été effectué. La connexion MCP est fonctionnelle; l’interprétation automatique par un LLM reste à montrer lors de la démonstration manuelle. Les chaînes extraites des fichiers sont des données non fiables, jamais des instructions.'))
page('10 / TRIAGE STATIQUE','Méthode de triage statique',table(['Mesure','Résultat du fixture inerte'],[['Taille',str(triage['bytes'])+' octets'],['Type','Texte Unicode UTF-8'],['Entropie',str(triage['entropy'])+' bits par octet'],['Exécution','false : aucun fichier exécuté'],['YARA',', '.join(triage['yara_matches'])],['Indicateur réseau','https://telemetry.invalid/training'],['Verdict','Indeterminate; les indicateurs seuls ne prouvent pas un malware']])+f'''<h2>Empreinte SHA-256</h2><pre class="hash">{triage['sha256']}</pre><h2>Méthode et confiance</h2><p>Le triage est limité à 10 MiB. Il extrait l’empreinte, la taille, l’entropie, les chaînes imprimables et les URI, puis utilise file et les règles YARA locales avec délais bornés. Le worker s’exécute avec UID/GID 65534, sans capacité effective et sans droit d’écriture dans les preuves.</p><p>Le fichier de formation contient volontairement des marqueurs PowerShell, une instruction de prompt injection et une chaîne HTML hostile. Ils sont analysés comme du texte. Les correspondances YARA sont des indicateurs pédagogiques; elles ne constituent pas une classification validée de malware réel.</p>'''+box('Extension raisonnable','Ajouter des jeux de fichiers bénins/malveillants autorisés, mesurer faux positifs et faux négatifs, puis isoler toute analyse dynamique dans des VM jetables séparées du poste personnel.'))
page('11 / SÉCURITÉ','Évaluation de la sécurité',table(['Contrôle observé','Résultat'],[['Sortie station vers 1.1.1.1:443','Refusée; référence hôte accessible'],['Sentinelle sur passerelle hôte','Refusée depuis les deux conteneurs'],['Racine en lecture seule','Écritures refusées pour trois acteurs'],['Seccomp / no-new-privileges','Actifs'],['Socket Docker / périphériques hôte','Absents'],['PID / IPC hôte','Non partagés'],['Création namespace mount','Refusée'],['Worker : écriture samples / preuves','Refusée'],['Protection du bridge absente','Triage MCP refusé; succès après restauration'],['IPv6 conteneurs','Désactivé']])+'''<h2>Ce qui reste dans le périmètre de confiance</h2><p>L’hôte WSL2, Docker, l’utilisateur et le serveur MCP sont de confiance. Le filtrage du bridge bloque les nouvelles connexions vers l’hôte et autorise les réponses aux connexions initiées par l’hôte. Un administrateur peut modifier ces protections.</p><p>Versions observées : Docker 27.5.1+dfsg4, runc 1.3.3+ds1 et noyau 6.18.33.2-microsoft-standard-WSL2. Ces versions ne démontrent pas une absence universelle de vulnérabilités.</p>'''+box('Limite fondamentale','Docker partage le noyau WSL2 : aucune garantie absolue d’absence d’évasion. Aucun malware inconnu n’est exécuté. Les parseurs statiques peuvent aussi comporter des failles. Une VM distincte est nécessaire pour envisager une analyse dynamique de malware réel.'))
page('12 / CONCLUSION & ANNEXES','Bilan et dossier de livraison', '''<p class="lead">La solution relie les actions, les observations, les protections et les preuves dans un workflow reproductible et économe.</p><h2>Bilan</h2><p>Les scénarios reproduisent les comportements attendus et mesurent les mitigations sans données réelles. Le dossier distingue une tentative détectée de son succès observé. Le MCP ajoute un accès borné aux artefacts; la validation ne prétend pas remplacer un audit de sécurité du noyau ni un IDS de production.</p>'''+table(['Livrable','Emplacement'],[['Dossier interactif','START-HERE.html'],['Vue technique','presentation.html; docs/RUNBOOK.md'],['Preuves',E.name+' : PCAP, JSONL, TSV, XML, PNG'],['Tests','tests/; scripts/runtime_checks.py; sandbox_audit.py'],['Intégrité','SHA256SUMS dans le dossier de preuves'],['Guide MCP','docs/AI-MCP.md; opencode.json'],['Arrêt du laboratoire','./scripts/lab.sh down']])+'''<h2>Points restant manuels</h2><p>Dialogue avec le modèle IA et utilisation de Burp GUI/Repeater. Burp Suite Community 2025.10.6-43347 est installé et son lancement CLI est vérifié; aucune session Burp automatisée n’est revendiquée.</p><h2>Références techniques</h2><p class="refs">Docker Compose : docs.docker.com/reference/compose-file/networks/ et services/<br>Wireshark/TShark : wireshark.org/docs/man-pages/tshark<br>MCP Python SDK : github.com/modelcontextprotocol/python-sdk<br>OpenCode : docs.opencode.ai/docs/mcp-servers/ et permissions/<br>runc : github.com/opencontainers/runc/security/advisories/GHSA-9493-h29p-rfm2</p>''')
css='''@page{size:A4;margin:0}*{box-sizing:border-box}body{margin:0;font-family:"DejaVu Sans",Arial,sans-serif;color:#183043;font-size:9.6pt;line-height:1.48;-webkit-print-color-adjust:exact;print-color-adjust:exact}.page{width:210mm;height:297mm;padding:19mm 18mm 20mm;position:relative;break-after:page;overflow:hidden;background:#fafcfd}.page:last-child{break-after:auto}.kicker{font-size:8pt;color:#13856d;letter-spacing:2px;font-weight:700;border-bottom:1px solid #cbd9df;padding-bottom:4mm}h1{font-size:26pt;line-height:1.12;letter-spacing:-1px;margin:7mm 0 5mm;color:#112a3c}h2{font-size:14pt;margin:5mm 0 2mm;color:#126f61}p{margin:2.5mm 0 4mm}.lead{font-size:14pt;line-height:1.5;color:#446172}table{border-collapse:collapse;width:100%;font-size:8.6pt;margin:4mm 0}th{text-align:left;background:#142f42;color:white;padding:3mm}td{padding:2.2mm;border-bottom:1px solid #d5e1e6;vertical-align:top}tr:nth-child(even) td{background:#edf4f6}aside{background:#e6f4ef;border-left:3px solid #119c7b;padding:3mm 4mm;margin:4mm 0}aside p{margin:1.5mm 0;font-size:9.3pt}footer{position:absolute;bottom:10mm;left:18mm;right:18mm;border-top:1px solid #cad8df;padding-top:3mm;display:flex;justify-content:space-between;font-size:6.6pt;letter-spacing:.5px;color:#547080}pre{white-space:pre-wrap;background:#142f42;color:#d5f9ee;border-radius:3mm;padding:4mm;font:9pt monospace}.hash{font-size:8pt;word-break:break-all}code{font-size:9pt;background:#e5edf0;padding:1px 3px}.topology{display:flex;align-items:center;justify-content:space-between;background:#e8f2f3;padding:6mm;margin:6mm 0}.topology div{font-size:10pt}.topology b{display:block;font-size:17pt;color:#0f8972}.topology small{display:block}.topology strong{font-size:9pt}.flow{background:#142f42;color:#c6f7e8;padding:5mm;font-weight:700;border-radius:3mm}figure{margin:4mm 0 6mm}figure img{width:100%;max-height:83mm;object-fit:contain;background:#e5edf1;border:1px solid #cbd7df}figcaption{font-size:8pt;color:#577181;margin-top:2mm}.dashboard img{max-height:175mm}.fine,.refs{font-size:8.4pt}.cover{background:#10283a;color:#eef8fa;padding-top:23mm}.cover .kicker{color:#83dec3;border-color:#456372}.cover h1{font-size:58pt;color:#fff;letter-spacing:-3px;line-height:.99;margin:17mm 0 10mm}.cover em{font-style:normal;color:#76dcb8}.cover h2{color:#b8d0dd;font-size:15pt;line-height:1.6;font-weight:400}.authors{font-weight:700;font-size:18pt;letter-spacing:1px;margin-top:17mm}.subtitle{color:#91acbd;font-size:8.5pt;letter-spacing:1px;margin-top:5mm}.coverstats{display:flex;gap:12mm;margin-top:12mm}.coverstats span{font-size:8pt;color:#bed6df}.coverstats b{display:block;font-size:29pt;color:#79dfbd}.cover footer{color:#a8c4d1;border-color:#3b5668}.coverline{width:24mm;height:2mm;background:#80e3bc;margin-top:8mm}'''
css+='''body{font-family:"Liberation Sans",Arial,sans-serif;color:#252b33;background:white;line-height:1.5}.page{background:#fff}.kicker{color:#526071;letter-spacing:1px;font-size:7.5pt;border-color:#cbd0d6}h1{font-size:25pt;letter-spacing:-.3px;color:#1c3048;line-height:1.2;margin:8mm 0 6mm}h2{color:#263c55;font-size:12pt;font-weight:700}.lead{font-size:12pt;color:#3e4753}th{background:#243b55;font-size:8.5pt}tr:nth-child(even) td{background:#f4f5f7}td{border-color:#dfe2e6}aside{background:#f3f4f6;border-left:2px solid #63778d;padding:3mm 4mm}aside b{color:#263b53}pre{background:#f1f3f5;color:#25384e;border:1px solid #dde1e6;border-radius:0}.topology{background:#f2f4f7;border:1px solid #d6dce3}.topology b{color:#243b55;font-size:15pt}.flow{background:#f1f3f6;border:1px solid #d3dae2;color:#253b55;border-radius:0}footer{color:#69727e;border-color:#d4d8dd;letter-spacing:0;font-size:7pt}figcaption{color:#566170}figure img{border-color:#cdd2d9}.cover{background:#fff;color:#263343;padding:22mm 20mm}.cover .kicker{color:#526071;border-color:#bdc6d1}.document-type{margin-top:20mm;color:#627084;font-size:10pt;letter-spacing:2px}.cover h1{font-family:"Liberation Serif",Georgia,serif;font-size:35pt;color:#1e334c;letter-spacing:-.4px;line-height:1.2;margin:8mm 0 6mm}.cover h2{font-size:18pt;color:#596777;font-weight:400;line-height:1.3;margin:0}.coverline{background:#294560;width:100%;height:.5mm;margin:10mm 0}.scope{font-size:11pt;color:#4f5c6b;line-height:1.8}.authors{font-size:15pt;color:#263d55;letter-spacing:.3px;line-height:1.7;margin-top:20mm}.label{font-size:8pt;color:#6d7886;letter-spacing:1px;font-weight:400}.subtitle{font-size:10pt;letter-spacing:0;color:#647181;margin-top:8mm}.cover-note{font-size:9pt;color:#6c7682;line-height:1.6;margin-top:14mm}.cover footer{color:#6c7682;border-color:#cbd2db}.cover footer span{font-size:7.5pt}'''

report=O/'CyberThreat-Technical-Report.html'
report.write_text('<!doctype html><html lang="fr"><head><meta charset="utf-8"><title>Rapport SSIR-5-F · WAEL RDIFI & RIM MENZLI</title><style>'+css+'</style></head><body>'+''.join(pages).replace(chr(8212), ':')+'</body></html>')
pdf=report.with_suffix('.pdf')
with sync_playwright() as p:
 browser=p.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox','--disable-gpu'])
 tab=browser.new_page();tab.goto(report.as_uri(),wait_until='load');tab.emulate_media(media='print')
 overflow=tab.locator('.page').evaluate_all('(els)=>els.map((e,i)=>({page:i+1,overflow:e.scrollHeight>e.clientHeight+2}))')
 assert not any(x['overflow'] for x in overflow),overflow
 tab.pdf(path=str(pdf),format='A4',print_background=True,prefer_css_page_size=True)
 browser.close()
export_dir=os.environ.get('CYBERTHREAT_EXPORT_DIR')
if export_dir:
 directory=Path(export_dir);directory.mkdir(exist_ok=True,parents=True)
 for f in [pdf,report]:
  if (directory/f.name).resolve()!=f.resolve():shutil.copy2(f,directory/f.name)
print(f'Created {len(pages)} pages: {pdf}; {pdf.stat().st_size} bytes')
